  const driverReviewSteps=[{key:'dl',kind:'dl',checks:['dl']},{key:'rc',kind:'rc',checks:['rc']},{key:'insurance',kind:'insurance',checks:['insurance']},{key:'selfie',kind:'selfie',checks:['identity_match']}];
