  function canSaveStep(a,key,values){const record=progressEntry(a),step=record?.data?.steps?.find(x=>x.key===key),cfg=driverReviewSteps.find(x=>x.key===key),doc=(a.documents||[]).find(x=>x.id===step?.document_id),saved=step?.checks||{},complete=step?.complete===true,read=complete||Boolean(doc&&hasViewedAllPages(a,doc)),allChecked=Boolean(cfg&&cfg.checks.every(k=>values?.[k]===true)),changed=Boolean(cfg&&cfg.checks.some(k=>(values?.[k]===true)!==(saved[k]===true)));return read&&(allChecked||(complete&&changed))&&!record?.stale;}
  function reviewProgressReady(a){const record=progressEntry(a);if(!record?.data?.ready_for_approval||record.loading||record.stale)return false;return driverReviewSteps.every(cfg=>{const server=record.data.steps.find(x=>x.key===cfg.key),local=reviewStepDrafts.get(`${progressKey(a)}:${cfg.key}`);return server?.complete===true&&(!local||cfg.checks.every(k=>(local[k]===true)===(server.checks?.[k]===true)));});}
  function captureReviewStep(form){const a=(current()?.data?.applications||[]).find(x=>x.id===form.dataset.afId);if(!a)return;const key=progressKey(a),step=form.dataset.afStep,values=stepValues(form);reviewStepDrafts.set(`${key}:${step}`,values);const button=form.querySelector('[data-af-save-step]');if(button)button.disabled=busy||!canSaveStep(a,step,values);const review=form.closest('[data-af-application]')?.querySelector('form[data-af-form="review-application"]'),select=review?.elements.decision;if(select){const approved=select.querySelector('option[value="approved"]'),ready=reviewProgressReady(a);if(approved)approved.disabled=!ready;if(!ready&&select.value==='approved')select.value='needs_changes';const notice=review.querySelector('[data-af-progress-dirty]');if(notice)notice.hidden=ready;}}
  async function loadReviewProgress(a,force=false,options={}){if(!caps().includes('verify.review')||a.status!=='submitted')return;const key=progressKey(a),old=reviewProgress.get(key);if(old?.loading||(!force&&(old?.data||old?.attempted)))return;const revision=epoch,owner=state.user?.id,view=route;reviewProgress.set(key,{...old,loading:true,attempted:true,error:options.notice||''});try{const data=await api(`/api/driver_review_progress?application_id=${encodeURIComponent(a.id)}`);if(epoch!==revision||owner!==state.user?.id||route!==view)return;if(data.application_id!==a.id||data.application_version!==a.version||!Number.isInteger(data.revision)||!Array.isArray(data.steps))throw Object.assign(new Error(t('afProgressVersionConflict')),{code:'review_progress_version_conflict',status:409});reviewProgress.set(key,{data,loading:false,error:options.notice||'',stale:options.stale===true});if(!reviewActive.has(key))reviewActive.set(key,data.current_step||driverReviewSteps.at(-1).key);}catch(error){if(epoch!==revision||owner!==state.user?.id||route!==view)return;reviewProgress.set(key,{...old,loading:false,attempted:true,error:progressError(error),stale:options.stale===true});if(error.status===401)await expire();else if(error.code==='verification_forbidden')await clearReviewAccess();else if(error.code==='review_progress_version_conflict'){const entry=current()||{};cache.set(view,{...entry,loaded:false,notice:'afProgressVersionConflict'});void load(true);}}finally{if(epoch===revision&&owner===state.user?.id&&route===view)render();}}
