  function backReviewStep(button){const a=(current()?.data?.applications||[]).find(x=>x.id===button.dataset.afId);if(!a)return;const form=button.closest('form[data-af-form="review-step"]');if(form)captureReviewStep(form);const key=progressKey(a),active=reviewActive.get(key)||progressEntry(a)?.data?.current_step||driverReviewSteps.at(-1).key,index=driverReviewSteps.findIndex(x=>x.key===active);if(index>0){reviewActive.set(key,driverReviewSteps[index-1].key);render();}}
  function resetReviewStep(button){const a=(current()?.data?.applications||[]).find(x=>x.id===button.dataset.afId);if(!a)return;const key=progressKey(a),record=progressEntry(a);reviewStepDrafts.delete(`${key}:${button.dataset.afStep}`);if(record)reviewProgress.set(key,{...record,stale:false,error:''});reviewActive.set(key,record?.data?.current_step||driverReviewSteps.at(-1).key);render();}

  function owns(value){return ['payments','verification','reviews','verification-queue','account-security'].includes(value)||value.startsWith('payment/')||value.startsWith('trip-budget/')||value.startsWith('driver/');}
  function endpoint(value){if(value==='account-security')return '/api/account/lifecycle';if(value.startsWith('trip-budget/'))return `/api/payments/trip-budget/${encodeURIComponent(decodeURIComponent(value.slice(12)))}`;if(value==='verification')return '/api/driver_application';if(value==='verification-queue')return '/api/verification_queue';if(value==='payments')return '/api/payments';if(value==='reviews')return '/api/reviews';if(value.startsWith('payment/'))return `/api/payment?booking_id=${encodeURIComponent(decodeURIComponent(value.slice(8)))}`;return `/api/driver_profile?user_id=${encodeURIComponent(decodeURIComponent(value.slice(7)))}`;}
  function capture(){if(!root)return;for(const form of root.querySelectorAll('form[data-af-form]')){if(form.dataset.afForm.startsWith('life-'))continue;const values={};for(const el of form.elements){if(!el.name||el.type==='file')continue;values[el.name]=el.type==='checkbox'?el.checked:el.value;}drafts.set(form.dataset.afDraft||form.dataset.afForm,values);}}
