  async function load(force=false){const view=route,owner=state.user?.id,revision=epoch;if(!owns(view)||!owner)return;let entry=cache.get(view);if(entry?.loading||(!force&&entry?.loaded))return;entry={...entry,loading:true,error:null};cache.set(view,entry);try{const data=await api(endpoint(view));if(epoch!==revision||state.user?.id!==owner)return;cache.set(view,{...entry,data,loaded:true,loading:false,error:null});if(view==='verification-queue')preloadReviewProgress(data.applications||[],force);}catch(error){if(epoch!==revision||state.user?.id!==owner)return;cache.set(view,{...entry,loading:false,loaded:true,error:errorMessage(error)});if(error.status===401)await expire();else if(error.code==='verification_forbidden')await clearReviewAccess();}finally{if(epoch===revision&&route===view&&state.user?.id===owner)render();}}
  const errorBlock=entry=>entry?.error?`<div class="alert error" role="alert">${esc(entry.error)} ${button('retry','reload')}</div>`:'';
  function page(value){prepare(value);const entry=current(), title=value==='account-security'?'lcSecurity':value.startsWith('trip-budget/')?'afTripBudget':value==='payments'?'afPayments':value==='verification'?'afVerification':value==='verification-queue'?'afQueue':value==='reviews'?'afReviews':value.startsWith('driver/')?'afDriverProfile':'afContribution';let body='';if(!entry?.loaded)body=note(`${busyMark()} ${t('loading')}`);else if(!entry.data)body=errorBlock(entry);else {body=errorBlock(entry)+(entry.notice?note(t(entry.notice)): '');body+=value==='account-security'?lifePage(entry.data):value.startsWith('trip-budget/')?tripBudget(entry.data):value==='payments'?payments(entry.data):value.startsWith('payment/')?payment(entry.data):value==='verification'?application(entry.data):value==='verification-queue'?queue(entry.data):value==='reviews'?reviews(entry.data):driver(entry.data);}
    return `<section class="af-page"><header class="page-head"><a class="back" href="#/${value==='verification-queue'?'operations':'profile'}">${icon('arrowLeft',20)} ${t('back')}</a><div><h1>${t(title)}</h1></div>${button('refresh','reload')}</header>${body}</section>`;}
